import re
from fractions import Fraction

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)")
_COMPOUND = re.compile(r"(?:\s*" + _NUM + r"\s*[A-Za-z]+)+\s*")
_ISO = re.compile(
    r"P(?:(\d+)W)?(?:(\d+)D)?"
    r"(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?",
    re.IGNORECASE,
)
_CLOCK = re.compile(r"\d+(?::\d+){1,2}(?:\.\d+)?")
_INT = re.compile(r"\d+")


def _round(total):
    # round half up to nearest whole second, exact arithmetic
    return int((total + Fraction(1, 2)) // 1)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if _INT.fullmatch(s):
        return int(s)

    if s[0] in "Pp":
        if s[-1] == "T" or s[-1] == "t" or s.upper() == "P":
            raise ValueError(f"invalid ISO duration: {text!r}")
        m = _ISO.fullmatch(s)
        if not m:
            raise ValueError(f"invalid ISO duration: {text!r}")
        weeks, days, hours, mins, secs = (int(g) if g else 0 for g in m.groups())
        if "T" in s.upper() and not re.search(r"[HMS]", s.upper().split("T", 1)[1]):
            raise ValueError(f"invalid ISO duration: {text!r}")
        return weeks * 604800 + days * 86400 + hours * 3600 + mins * 60 + secs

    if _CLOCK.fullmatch(s):
        fields = s.split(":")
        total = Fraction(0)
        for f in fields:
            total = total * 60 + Fraction(f)
        return _round(total)

    if _COMPOUND.fullmatch(s):
        total = Fraction(0)
        pos = 0
        while pos < len(s):
            m = _COMPONENT.match(s, pos)
            if not m:
                raise ValueError(f"invalid duration: {text!r}")
            num, unit = m.group(1), m.group(2).lower()
            if unit not in _UNITS:
                raise ValueError(f"unknown unit {unit!r} in {text!r}")
            total += Fraction(num) * _UNITS[unit]
            pos = m.end()
            while pos < len(s) and s[pos].isspace():
                pos += 1
        return _round(total)

    raise ValueError(f"invalid duration: {text!r}")

